import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { call, rarityName, t } from '../util';
import { loadStyles } from '../styles';
/** Pick one of your own stickers to put on a post (or take yours off). */
export default class ReactionModal extends Modal {
  oninit(vnode) {
    super.oninit(vnode);
    loadStyles();
    this.stickers = null;
    this.filter = '';
    call('GET', '/mine').then(data => this.stickers = data.stickers).catch(() => this.stickers = []).finally(() => m.redraw());
  }
  className() {
    return 'StickerReactionModal Modal--small';
  }
  title() {
    return t('react.title');
  }
  content() {
    if (!this.stickers) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, null));
    if (!this.stickers.length) {
      return m("div", {
        className: "Modal-body StickerReact-empty"
      }, m("p", null, t('react.none')), m(Link, {
        className: "Button Button--primary",
        href: app.route('stickers'),
        onclick: () => this.hide()
      }, t('react.go')));
    }
    return this.picker(this.stickers);
  }

  /** The member's stickers to pick from, filtered by name once there are many. */
  picker(stickers) {
    const mine = (this.attrs.post.attribute('stickerReactions') || []).find(r => r.mine);
    const q = this.filter.trim().toLowerCase();
    const shown = q ? stickers.filter(s => s.name.toLowerCase().includes(q)) : stickers;
    return m("div", {
      className: "Modal-body"
    }, stickers.length > 12 ? m("input", {
      className: "FormControl StickerReact-filter",
      placeholder: extractText(t('react.filter')),
      value: this.filter,
      oninput: e => this.filter = e.target.value
    }) : null, m("div", {
      className: "StickerReact-grid"
    }, shown.map(s => m("button", {
      className: `StickerReact-pick StickerTile--r${s.rarity} ${mine?.id === s.id ? 'is-mine' : ''}`,
      title: `${s.name} · ${rarityName(s.rarity)}`,
      disabled: this.saving,
      onclick: () => this.react(mine?.id === s.id ? null : s.id)
    }, m("img", {
      src: s.small,
      alt: s.name
    })))), mine ? m(Button, {
      className: "Button Button--link",
      onclick: () => this.react(null)
    }, t('react.remove')) : null);
  }
  react(sticker) {
    this.saving = true;
    react(this.attrs.post, sticker).then(() => this.hide()).catch(() => {
      /* call() already showed the error */
    }).finally(() => this.saving = false);
  }
}
export function react(post, sticker) {
  return call('POST', '/react', {
    post: post.id(),
    sticker
  }).then(data => {
    post.pushAttributes({
      stickerReactions: data.reactions.length ? data.reactions : null
    });
    m.redraw();
  });
}
flarum.reg.add('ernestdefoe-sticker-book', 'forum/components/ReactionModal', ReactionModal);